INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'Biology', 'Unit 1', 'Molarum Grade 10 — Biology Sub-fields of Biology', 'Source-grounded Molarum Grade 10 Biology questions for Sub-fields of Biology.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('405c4d61-2098-4c25-8ca1-5a1d2fcac5dc'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which of the following best describes the THINK-PAIR-SHARE activity as presented in Activity 1.1?', 'A collaborative learning strategy where students think individually, pair with a partner, then share with the class.', 'Think-PAIR-SHARE is a collaborative learning strategy designed to promote discussion and reflection.', 0),('f8674dcd-7ccf-4957-8e39-b4ae79e477f4'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which field studies the arrangement and structure of cells?', 'Cell biology', 'Cell biology focuses on cellular structure and function.', 1),('1b9ed79e-ed19-490f-89f5-02138a00412b'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which subject is commonly studied within physiology-related branches?', 'Physiology', 'Physiology deals with functions of organisms and systems.', 2),('ef5260a1-f216-40d3-841f-a70bc293d98f'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which subject from outside biology is most commonly used to explain diffusion and chemical gradients in biology?', 'Chemistry', 'Chemistry provides concepts of diffusion, concentration, and gradients used in biology.', 3),('9b8451f1-cba9-4e75-8425-b1af3ca8c802'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which option best identifies a bacterium?', 'Escherichia coli', 'Escherichia coli is a bacterium; Amoeba is a protozoan, Yeast is fungi, Algae are photosynthetic protists.', 4),('69420c62-3be6-407b-85b8-addbef319b77'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'true_false', 'Think-Pair-Share is primarily an individual activity with no collaboration.', 'False', 'Think-Pair-Share involves individual thinking, pair discussion, and sharing with the class.', 5),('e481e756-ea9f-4e64-8048-9cb9cefe0993'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'Name one subject studied in the branches of biology as listed in Table 1.2.', 'Genetics', 'Table 1.2 lists several subjects; genetics is a common example.', 6),('6b284819-b3b3-4a49-875a-99fa1372c406'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'Explain one advantage of Think-Pair-Share in learning biology.', 'Encourages collaboration and deeper understanding', 'Group discussion can enhance comprehension and retention.', 7),('d583c2d1-765a-48db-8f53-fd4b2c4f4297'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'From Table 1.1, suppose there are 4 main fields of biology based on the structure studied. If each field has 3 main subfields, how many subfields exist in total?', '12', 'Total subfields = 4 × 3 = 12.', 8),('de0b285c-1d9d-4a76-832b-b3761e816d35'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'From Table 1.2, assume there are 3 branches of biology and each branch has 4 subjects. How many subjects are there in total?', '12', 'Total subjects = 3 × 4 = 12.', 9),('3248ef87-25df-4a97-890d-da69f9dcd2e2'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which field of biology studies body structures such as organs and tissues based on their anatomy?', 'Anatomy', 'Anatomy focuses on the structure of organisms, a key aspect in Table 1.1.', 10),('f766e9d0-73b9-4814-8564-69927f45221e'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which branch studies how the body functions and maintains homeostasis?', 'Physiology', 'Physiology deals with the function of organisms and their parts.', 11),('8590d331-8fe9-44e5-89dc-5308246187c7'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'In the Think-Pair-Share activity, what is the primary purpose of pairing students to discuss a question before sharing with the class?', 'To generate ideas collaboratively', 'Think-Pair-Share is designed to promote collaborative idea generation.', 12),('cb28e277-ef80-4aa8-86b0-9394d20fc8b8'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which other subject is commonly cited as helping explain the chemical basis of life in biological phenomena?', 'Chemistry', 'Chemistry provides the chemical principles underpinning biology.', 13),('840ccd92-b8d2-4907-81b8-a438aa235ec3'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'In the study of microorganisms, which field specifically focuses on bacteria, viruses, and fungi?', 'Microbiology', 'Microbiology is the study of microorganisms including bacteria, viruses, and fungi.', 14),('f274f03b-d10a-4d5d-8072-50be9ad23a4c'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'true_false', 'Physiology is the branch of biology that studies the function of living organisms.', 'True', 'Physiology analyzes how organisms perform life processes.', 15),('9d2555d1-e8b3-48c2-84fc-23709681a063'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'Name two sub-fields of biology that study body structure.', 'Anatomy; Morphology', 'Anatomy and Morphology focus on the structure of organisms.', 16),('ac41dbf4-c40a-48eb-82fa-1dc16f7f0fce'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'In a class of 16 students participating in Think-Pair-Share, how many pairs are formed?', '8', 'Number of pairs equals the number of students divided by 2 (16 / 2 = 8 pairs).', 17),('0516db64-edd4-4744-87f5-ac90cbf534e5'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'From Table 1.2, name one branch of biology and its focus.', 'Physiology — function of organs', 'Physiology focuses on the function of organ systems as listed in Table 1.2.', 18),('83238473-b174-4d61-8aaf-82674a244b6b'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'In a microorganism count from a sample: bacteria = 2, viruses = 1, fungi = 1, protozoa = 1; total observed = 5. What percentage of observed microorganisms are bacteria?', '40%', 'Percentage of bacteria = (2/5) x 100 = 40%.', 19),('95b0ec93-ddbf-4479-8193-69e3fee925df'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which sub-field of biology studies the structure of organisms, from tissues down to organs?', 'Anatomy', 'Anatomy focuses on the physical structure and organization of the body.', 20),('eb3f2192-d71d-434b-81e2-bcc0882dfbd1'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which sub-field is primarily concerned with the function of living systems?', 'Physiology', 'Physiology studies the functions of organs and systems.', 21),('e083c266-34e2-40d3-8cfd-bfa1a21c705a'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which sub-field studies cells and their components?', 'Cytology', 'Cytology examines cell structure and function.', 22),('03b82610-6637-4447-8b7f-5bb1b6151d2b'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which branch studies plants?', 'Botany', 'Botany focuses on plant life.', 23),('4c567a14-32a8-45c4-8eb2-9f3720ba294c'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which branch studies animals?', 'Zoology', 'Zoology studies animal life.', 24),('80f8cff5-92af-4c22-84b9-862a85bc6987'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'true_false', 'Biology relies on knowledge from other sciences?', 'False', 'Biology uses knowledge from other sciences to explain phenomena; it is not isolated from them.', 25),('5c959fdd-34ce-4da8-86c1-ff76fbe2de70'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'Name one branch of biology that studies plants.', 'Botany', 'Botany is the branch that studies plants.', 26),('1fc9f67a-1982-4f7e-8e5a-34b8c21a2aaa'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'Explain the difference between anatomy and physiology using the human heart as an example.', 'Anatomy describes the heart''s structure (chambers, valves, walls) and physiology describes its function (pumping blood, regulating circulation); together they explain how the heart is built and how it works.', 'Anatomy focuses on structure; physiology focuses on function; the heart provides a concrete example of both.', 27),('a5871cb1-cea8-42cb-8d12-28e4e0383ef1'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'A microorganism doubles every 45 minutes. If starting with 200 cells, how many cells are there after 3 hours?', '3200 cells', 'Number of doublings in 3 hours: 180 minutes / 45 minutes = 4 doublings. Final count N = 200 × 2^4 = 200 × 16 = 3200 cells.', 28),('873ef485-87fa-4a69-8bc4-62da93b3c93d'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'If a culture doubles every 60 minutes, starting from 500 cells, how many cells will be present after 4 hours?', '8000 cells', 'Number of doublings in 4 hours: 240 minutes / 60 minutes = 4 doublings. Final count N = 500 × 2^4 = 500 × 16 = 8000 cells.', 29),('371b3910-1464-4bf1-81ea-6e758fb3e63e'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which sub-field of biology studies the basic unit of life, the cell?', 'Cytology', 'Cytology is the study of cells, one of the fields listed under Table 1.1 which groups biology by the structure studied.', 30),('63c51446-9046-444c-89b2-218164524873'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which sub-field studies the structure and organization of organs in the body?', 'Anatomy', 'Anatomy deals with organs and their relationships, a field listed under Table 1.1 based on structure.', 31),('597efa0d-bb87-41a6-8870-a4c2a9f4081a'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'From Table 1.2, which subject is primarily concerned with heredity and variation?', 'Genetics', 'Genetics deals with heredity and variation, as listed in Table 1.2.', 32),('310e544f-9ae2-4729-8de5-255a411daacf'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which activity is described in Unit 1 to promote discussion of sub-fields of biology?', 'Activity 1.1', 'Activity 1.1 is the Think-Pair-Share activity mentioned in Unit 1 for discussing sub-fields.', 33),('66083c97-b573-4054-8ae3-74a08667fe98'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'multiple_choice', 'Which subject listed in Table 1.3 helps explain biological phenomena using mathematical relationships?', 'Mathematics', 'Table 1.3 includes Mathematics as a knowledge source that helps explain biological phenomena using quantitative tools.', 34),('17f2571d-26fa-4984-8fa8-2d6af9c1305a'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'true_false', 'The statement ''All biology sub-fields are defined only by the structure studied'' is true.', 'False', 'While some fields are based on structure, others are also defined by function or application (as seen in Activity 1.1 and Table 1.3).', 35),('6952b927-3727-4ee3-8037-8d28297e7fe9'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'Name two sub-fields of biology based on the structure studied.', 'Cytology and Histology', 'Cytology and Histology are commonly cited as structure-based sub-fields (cells and tissues).', 36),('bb82f718-87ed-4a9a-890b-0fcdb34b4310'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'From Table 1.2, name a branch of biology that studies living organisms and their interactions with the environment.', 'Ecology', 'Ecology is the branch that focuses on organisms and their interactions with the environment as listed in Table 1.2.', 37),('688e237a-2bc1-4a43-8c1f-31f7508e3111'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'There are four fields of biology based on the structure studied (Cytology, Histology, Anatomy, Morphology). If a student lists two additional fields based on function, what percentage of the total listed fields are structure-based? Show your calculation and units.', '66.7%', 'Structure-based fields = 4; function-based fields = 2; total = 6; percentage = (4/6) x 100 = 66.7%.', 38),('a480addf-fd5b-4102-893a-cb384a500ee5'::uuid, 'f558ab39-25e4-49d0-8bad-f495073d5f9d'::uuid, 'fill_blank', 'Table 1.2 lists four branches: Botany, Zoology, Microbiology, Ecology. If two more organism-focused branches Genetics and Physiology are added, what percentage of the six branches focus on living organisms? Show your calculation and units.', '83.3%', 'Living-organism branches among the six: Botany, Zoology, Microbiology, Genetics, Physiology = 5; Percentage = (5/6) x 100 = 83.3%.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('fac4ba10-b359-4c41-8210-3c318ed551af'::uuid, '405c4d61-2098-4c25-8ca1-5a1d2fcac5dc'::uuid, 'A collaborative learning strategy where students think individually, pair with a partner, then share with the class.', TRUE, 0),('bb9f1fed-3914-46d6-8be8-9e8e53365e73'::uuid, '405c4d61-2098-4c25-8ca1-5a1d2fcac5dc'::uuid, 'A laboratory procedure for preparing biological samples.', FALSE, 1),('baf905f9-d2e4-441a-89ed-1efea0b82c2c'::uuid, '405c4d61-2098-4c25-8ca1-5a1d2fcac5dc'::uuid, 'A method for measuring plant growth.', FALSE, 2),('b828c3e9-4ed7-4a55-8375-42d1d6f65f03'::uuid, '405c4d61-2098-4c25-8ca1-5a1d2fcac5dc'::uuid, 'A way to organize field trips.', FALSE, 3),('c7f164e7-be7c-4537-80e9-903a60713c9d'::uuid, 'f8674dcd-7ccf-4957-8e39-b4ae79e477f4'::uuid, 'Cell biology', TRUE, 0),('a8a75978-3361-43b3-8564-99eb09b7ecfb'::uuid, 'f8674dcd-7ccf-4957-8e39-b4ae79e477f4'::uuid, 'Ecology', FALSE, 1),('5879cf4a-0e28-4e01-88c4-8042e29b80ee'::uuid, 'f8674dcd-7ccf-4957-8e39-b4ae79e477f4'::uuid, 'Genetics', FALSE, 2),('efa2e34b-996f-46d6-83c4-c18d6450ca09'::uuid, 'f8674dcd-7ccf-4957-8e39-b4ae79e477f4'::uuid, 'Physiology', FALSE, 3),('9093eaa7-35d8-441a-83a0-728775841632'::uuid, '1b9ed79e-ed19-490f-89f5-02138a00412b'::uuid, 'Physiology', TRUE, 0),('b5e58292-b323-4700-8d08-9056feedc980'::uuid, '1b9ed79e-ed19-490f-89f5-02138a00412b'::uuid, 'Taxonomy', FALSE, 1),('7ea0def8-1152-403e-81b3-edb10b1a6b2a'::uuid, '1b9ed79e-ed19-490f-89f5-02138a00412b'::uuid, 'Ecology', FALSE, 2),('9ce19d57-a546-4553-8a55-8727cdfe98fa'::uuid, '1b9ed79e-ed19-490f-89f5-02138a00412b'::uuid, 'Genetics', FALSE, 3),('780d8c26-4eef-4dda-80b5-faebb8c69166'::uuid, 'ef5260a1-f216-40d3-841f-a70bc293d98f'::uuid, 'Physics', FALSE, 0),('e88884b7-0176-45bd-815f-8a099d7d7950'::uuid, 'ef5260a1-f216-40d3-841f-a70bc293d98f'::uuid, 'Chemistry', TRUE, 1),('f8da8e17-c38f-473a-8111-d2f4d06aa2f4'::uuid, 'ef5260a1-f216-40d3-841f-a70bc293d98f'::uuid,