, 'Photosynthesis', TRUE, 1),('aa0ae1e6-c9ae-47df-8063-c3bcb45e4f6a'::uuid, 'faae4cc8-068e-4736-874c-a84c56298984'::uuid, 'Fermentation', FALSE, 2),('f62c653c-cbd8-4f55-8c90-7a603cbeca1c'::uuid, 'faae4cc8-068e-4736-874c-a84c56298984'::uuid, 'Transpiration', FALSE, 3),('7b2f475d-c448-499e-8fc6-9cd98dd84ed6'::uuid, '176de904-2093-4cdd-8932-e007adb3412b'::uuid, 'Roots', FALSE, 0),('a622ca5a-6d9e-47ad-8f30-ca2acd709cf0'::uuid, '176de904-2093-4cdd-8932-e007adb3412b'::uuid, 'Stomata in leaves', TRUE, 1),('15dc3c7c-cce1-455d-88a8-c5742d7c73dc'::uuid, '176de904-2093-4cdd-8932-e007adb3412b'::uuid, 'Flowers', FALSE, 2),('648420ad-b5c1-495e-82f7-d3e3e5e51012'::uuid, '176de904-2093-4cdd-8932-e007adb3412b'::uuid, 'Phloem', FALSE, 3),('1fa95baa-28ce-4a58-8b7a-7ef9706a3a56'::uuid, 'dc9404d0-c068-4ca7-86fa-81652aae75bf'::uuid, 'Bryophytes', FALSE, 0),('0c9a3771-a2e1-4270-871f-7f6449a93651'::uuid, 'dc9404d0-c068-4ca7-86fa-81652aae75bf'::uuid, 'Gymnosperms', TRUE, 1),('5b5ba5c9-c070-4440-8177-9a013fe70890'::uuid, 'dc9404d0-c068-4ca7-86fa-81652aae75bf'::uuid, 'Pteridophytes', FALSE, 2),('1b0adbdb-dd3f-451a-8730-90e9baba6983'::uuid, 'dc9404d0-c068-4ca7-86fa-81652aae75bf'::uuid, 'Algae', FALSE, 3),('ce8644cd-89a2-4c7e-828a-2f2060636dc2'::uuid, '89a8db4a-7b6f-4e4a-8a1c-9aa25f711728'::uuid, 'Absorbing water', FALSE, 0),('ef1d2bc7-9c7c-4fa1-8860-8376c48f681f'::uuid, '89a8db4a-7b6f-4e4a-8a1c-9aa25f711728'::uuid, 'Anchoring the plant', FALSE, 1),('31d7380a-b19e-4cd4-86c4-8c477f27068a'::uuid, '89a8db4a-7b6f-4e4a-8a1c-9aa25f711728'::uuid, 'Photosynthesis', TRUE, 2),('c833c82c-816e-4e5b-8274-9d1121f51b71'::uuid, '89a8db4a-7b6f-4e4a-8a1c-9aa25f711728'::uuid, 'Storage of nutrients', FALSE, 3),('0db80361-0c1b-4975-8c8c-b175b5a1c504'::uuid, '90e9dc1c-4c08-455e-8d39-36aa0f81775b'::uuid, 'True', FALSE, 0),('85708793-5fdc-484d-8613-8c0fc85a254a'::uuid, '90e9dc1c-4c08-455e-8d39-36aa0f81775b'::uuid, 'False', TRUE, 1),('b1efb452-2489-46fc-83db-4f76590e6fd1'::uuid, '68a6b179-a61e-4e11-852f-ba9aad70926e'::uuid, 'Bryophytes', FALSE, 0),('d9c28fa8-c4ec-4c5d-8266-ba027ae4edeb'::uuid, '68a6b179-a61e-4e11-852f-ba9aad70926e'::uuid, 'Pteridophytes', TRUE, 1),('89c8b823-3db8-4faa-83a5-a99dfe3e21e2'::uuid, '68a6b179-a61e-4e11-852f-ba9aad70926e'::uuid, 'Gymnosperms', FALSE, 2),('5e4618bc-5536-417e-8469-655547c4497b'::uuid, '68a6b179-a61e-4e11-852f-ba9aad70926e'::uuid, 'Angiosperms', FALSE, 3),('68b6c81d-9501-4219-8c3e-0a4141b623fc'::uuid, 'a7ce1a46-4ba6-4c94-8f0a-9aafbdde34f4'::uuid, 'Sugars for growth', FALSE, 0),('e7e5c578-04f3-492d-84f6-1e468d9db94f'::uuid, 'a7ce1a46-4ba6-4c94-8f0a-9aafbdde34f4'::uuid, 'Water and minerals', TRUE, 1),('d8066d65-b943-416d-8449-38fcf0b72fb9'::uuid, 'a7ce1a46-4ba6-4c94-8f0a-9aafbdde34f4'::uuid, 'Air for photosynthesis', FALSE, 2),('c657ab43-21b5-4e5f-8151-3447e00600e7'::uuid, 'a7ce1a46-4ba6-4c94-8f0a-9aafbdde34f4'::uuid, 'Proteins for storage', FALSE, 3),('92e4b9f8-2827-4db5-8456-801ab4933ca1'::uuid, '4d1d2f87-3d4d-4b3f-8b88-64e2a021138e'::uuid, 'They produce seeds in flowers', TRUE, 0),('45971315-8c67-4cfc-841b-5984ba7537c2'::uuid, '4d1d2f87-3d4d-4b3f-8b88-64e2a021138e'::uuid, 'They reproduce only asexually', FALSE, 1),('6e180198-944a-434c-8928-fd2232ae01ac'::uuid, '4d1d2f87-3d4d-4b3f-8b88-64e2a021138e'::uuid, 'They lack vascular tissue', FALSE, 2),('69c5aaaa-a9f2-472c-83dc-c4c9233df464'::uuid, '4d1d2f87-3d4d-4b3f-8b88-64e2a021138e'::uuid, 'They rely on spores for reproduction', FALSE, 3),('b6b206fc-80fc-4983-8033-15cddf463799'::uuid, '0f1348fc-56d8-41e4-826d-9fd1ecd97daa'::uuid, 'Ovary', FALSE, 0),('62b79670-4b0a-4d9f-8d37-9116dfc41a1c'::uuid, '0f1348fc-56d8-41e4-826d-9fd1ecd97daa'::uuid, 'Ovary wall', FALSE, 1),('bd7ada2f-f842-4e2e-8dfd-ce50c67e5ee0'::uuid, '0f1348fc-56d8-41e4-826d-9fd1ecd97daa'::uuid, 'Ovule', TRUE, 2),('68a1756d-531f-4d82-8ff1-6fdfca0d8ac8'::uuid, '0f1348fc-56d8-41e4-826d-9fd1ecd97daa'::uuid, 'Anther', FALSE, 3),('c3ed6e53-b78a-4f55-8588-9ee93aa955b0'::uuid, '199d0f06-eed8-43f0-8852-28c332f3ea65'::uuid, 'Respiration', FALSE, 0),('4f24207f-5963-40e8-88ff-a96cc4ba942b'::uuid, '199d0f06-eed8-43f0-8852-28c332f3ea65'::uuid, 'Fermentation', FALSE, 1),('192b2f5a-b9e3-4b5b-881a-5f8ee17f1976'::uuid, '199d0f06-eed8-43f0-8852-28c332f3ea65'::uuid, 'Transpiration', FALSE, 2),('292f1fa8-0b7d-4f76-810a-308c49457682'::uuid, '199d0f06-eed8-43f0-8852-28c332f3ea65'::uuid, 'Photosynthesis', TRUE, 3),('9a159acb-7167-4f47-86b9-e9a72c112c91'::uuid, '6f4424c2-c8eb-483e-8902-3bfd5ab222bf'::uuid, 'True', TRUE, 0),('ddd03f54-a7e3-405b-84d2-9a1739e6892c'::uuid, '6f4424c2-c8eb-483e-8902-3bfd5ab222bf'::uuid, 'False', FALSE, 1) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'Biology', 'Unit 3', 'Molarum Grade 10 — Biology Biochemical Molecules', 'Source-grounded Molarum Grade 10 Biology questions for Biochemical Molecules.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('866ac180-02df-4bd9-8fe3-ce1c8fcbc9f5'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Why water is considered a biochemical molecule?', 'It is the main solvent for biochemical reactions.', 'Water''s polarity makes it an excellent solvent for ionic and polar substances, enabling metabolic reactions.', 0),('e13084cb-c100-49b3-879a-1b4e57495040'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'What typical properties of water do you know?', 'Water polarity allows hydrogen bonding and dissolves many substances.', 'Water''s polarity enables hydrogen bonding, giving it properties like high solubility and high specific heat.', 1),('4f460f35-f517-4169-8f6d-d94985c2d6a0'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'What is the primary reason water has a bent molecular shape?', 'It has a bent shape because oxygen has two lone pairs, giving the molecule a V shape.', 'The two lone pairs on the oxygen atom repel bonding pairs, producing a bent geometry.', 2),('33bba12f-1574-4a72-8fb9-f6ee734dbfe0'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which process demonstrates how water moves up a plant stem due to cohesion and adhesion?', 'Both cohesion and adhesion enabling water transport in plants', 'Cohesion and adhesion work together to produce capillary action that helps water rise in xylem.', 3),('3ea821a1-6f4d-417d-8f61-db1e014ffac6'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'In a hydration shell around a cation like Na+, which part of the water molecule primarily orients toward the ion?', 'Water oxygen atoms face the cation (e.g., Na+).', 'The partially negative oxygen atoms face the positively charged ion, stabilizing the ion in solution.', 4),('9caaf39a-2df5-44fd-8ef7-aebdbeb087ee'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'true_false', 'Water is a polar molecule.', 'True', 'Water has a partial negative charge on the oxygen and partial positive charges on the hydrogen, giving it polarity.', 5),('d6bd6f4b-e9e7-4dc5-8b3a-16a54da88876'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Name two biological macromolecules formed by polymerization.', 'Proteins and nucleic acids.', 'Proteins (polypeptides) and nucleic acids (DNA/RNA) are major polymeric biomolecules.', 6),('cc78c881-08c7-4a27-8bed-4dfa127e4009'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Explain how enzymes act as biological catalysts in cells.', 'Enzymes speed up reactions by lowering activation energy and providing a specific active site; they are not consumed in the reaction.', 'Enzymes bind substrates at active sites, stabilize transition states, and lower the energy barrier.', 7),('d6fae94b-e65a-4478-8717-e127ad8c368e'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Calculate the molarity of a solution prepared by dissolving 5.0 g of glucose (C6H12O6, molar mass 180.16 g/mol) in enough water to make 250 mL of solution. Provide the answer in M (mol/L).', '0.111 mol/L', 'Moles of glucose = 5.0 g / 180.16 g/mol = 0.0278 mol. Volume = 0.250 L. Molarity = 0.0278 mol / 0.250 L = 0.111 M.', 8),('e403a754-7ebf-4fb5-8472-28f2fa00be0a'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Dilute 0.500 L of a 2.00 M NaCl solution to 1.000 L. What is the final molarity in M? Show the method and final unit.', '1.00 M', 'Using M1V1 = M2V2, M2 = (2.00 M × 0.500 L) / 1.000 L = 1.00 M.', 9),('80f6ae7d-b91d-4807-8c97-3ec9af350f09'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Why water is considered as a biochemical molecule?', 'Because it participates in chemical reactions and acts as a solvent in living organisms', 'Water participates in hydrolysis and condensation reactions, and serves as the medium in which many biochemical reactions occur.', 10),('65b1031d-f203-423f-8061-7a7d3838102b'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which property explains water''s high surface tension and capillary rise?', 'Hydrogen bonding between water molecules', 'Hydrogen bonding creates cohesion among water molecules, leading to high surface tension and the ability for capillary action.', 11),('08cb1411-016c-4b32-8903-b1734f9df0f3'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'In a water molecule, what is the approximate shape?', 'Bent (V-shaped)', 'Water has a bent shape with an angle of about 104.5 degrees due to the lone pairs on oxygen.', 12),('07626460-3e28-4540-847e-0b68446fcb22'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'When NaCl dissolves in water, what happens to the ions?', 'Ions are surrounded by water molecules (hydration)', 'Ions become hydrated in solution as water molecules surround them, allowing the salt to dissolve.', 13),('515efacf-0047-46c6-8c34-8e3a09a78783'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which statement best describes cohesion in water?', 'Water molecules stick to each other', 'Cohesion is the attraction between water molecules; adhesion is the attraction to other surfaces.', 14),('fe59b8d1-1513-4c5f-8791-d4dae6992979'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'true_false', 'Water is a universal solvent.', 'True', 'Water dissolves many substances, enabling biochemical reactions in living organisms.', 15),('fe3204a0-9664-4ed3-8277-93f744df1229'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Name two biomolecule categories that are essential for energy storage.', 'carbohydrates and lipids', 'Carbohydrates and lipids are primary energy storage biomolecules in living systems.', 16),('7583cf05-2c49-4bc1-85af-f87bc2b33b84'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Name one biomolecule that is a polymer of amino acids.', 'proteins', 'Proteins are polymers formed by linking amino acids.', 17),('1649d647-f9a8-4ca8-8d82-aacf11f54f47'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'What is the mass of 2.0 moles of water (H2O)?', '36.03 g', 'Mass = number of moles × molar mass. Molar mass of H2O is 18.015 g/mol. 2.0 mol × 18.015 g/mol = 36.03 g.', 18),('885bcb15-fa96-44ec-8515-ccbe531d658d'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'If 0.100 moles of glucose (C6H12O6) are dissolved in 1.00 L of solution, what is the molarity of the glucose solution?', '0.100 M', 'Molarity M = n/V. n = 0.100 mol, V = 1.00 L, so M = 0.100 mol/L (0.1 M).', 19),('84646107-e7d8-480a-8c84-6b2c2cd9ea7b'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Why is water considered a biochemical molecule?', 'A) It is the universal solvent for most biochemical reactions.', 'Water''s polarity allows it to dissolve many substances and participate in hydrolysis and condensation reactions in biology.', 20),('e41b2c7d-e65c-4bb5-8805-e166180b7771'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which property of water is most responsible for its high specific heat capacity in biological systems?', 'B) Hydrogen bonding between water molecules', 'Hydrogen bonds allow water to absorb a lot of heat before increasing in temperature, stabilizing body temperatures.', 21),('ff96c42b-420c-4c12-8351-d1b7b7618a92'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'In a water molecule, which element is the central atom?', 'B) Oxygen', 'Oxygen is the central atom in H2O with two hydrogen atoms bonded to it, giving the molecule a bent shape.', 22),('83b83c5a-eac4-40c4-89f2-88ba71e9ac03'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which process describes water molecules sticking to other surfaces (like glass)?', 'B) Adhesion', 'Adhesion is water''s tendency to cling to surfaces, while cohesion refers to water sticking to itself.', 23),('8a51adef-3932-422d-8eeb-1ca308ed5ae4'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which biomolecule is primarily used for long-term energy storage in animals?', 'C) Lipids', 'Lipids store energy efficiently and can provide long-term energy reserves.', 24),('ddad3e00-24aa-4ad4-8fa8-7959c234e770'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'true_false', 'Water molecules orient around dissolved ions due to their polar nature.', 'True', 'Polarity causes hydration shells around ions in solution.', 25),('10630178-05f7-40d0-8788-6bd6a2a7f2a9'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Explain in one sentence why water is considered a biochemical molecule.', 'Water is a biochemical molecule because of its polarity and hydrogen bonding, which enable many biochemical reactions and solvent properties.', 'Water’s polarity allows dissolution of substances and participation in hydrolysis/condensation reactions.', 26),('f4c36e34-3cd6-43ba-8fae-0b97662d5090'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Name two properties of water that support life and give one biological implication for each.', 'Polarity leading to solvent capability; Hydrogen bonding leading to high surface tension/thermal stability.', 'Polarity enables dissolution of ions and molecules; hydrogen bonding contributes to cohesion and thermal stability.', 27),('4d6773e6-555a-4c23-85d5-66352b1c27a8'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'A student dissolves 5.00 g of glucose (C6H12O6, molar mass = 180.16 g/mol) in water to make a final solution volume of 250.0 mL. What is the molarity (in mol/L) of the glucose in this solution? Show all steps and provide the final unit.', '0.111 M', 'moles of glucose = 5.00 g / 180.16 g/mol = 0.0278 mol; volume=0.250 L; M = 0.0278 / 0.250 = 0.111 M', 28),('669c1df5-bc45-4d8b-8fbe-039bd029fc5c'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'A solution is prepared by dissolving NaCl to make 0.50 L of a 0.150 M solution. How many moles of NaCl are present? Provide the calculation and final unit (moles).', '0.075 mol', 'moles = M × V = 0.150 mol/L × 0.50 L = 0.075 mol', 29),('af065264-8b58-4823-8753-a9036bde89e0'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Based on Unit 3, which statement best describes water''s typical properties in biology?', 'Water is a polar molecule that can dissolve many substances', 'Water''s polarity makes it an effective solvent for many biological molecules.', 30),('3e7ab41b-d164-441a-85e0-8e59e888e81a'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which statement explains why water is considered a biochemical molecule?', 'It participates in metabolic reactions and is essential for life', 'Water acts as solvent and reactant/product in many biological processes.', 31),('9886eb20-6be2-4d13-8bd2-2227202d8412'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'In one water molecule (H2O), how many hydrogen atoms are present relative to the oxygen atom? Provide the ratio and final unit.', '2:1 (H:O); dimensionless ratio', 'A water molecule consists of two hydrogen atoms bonded to one oxygen atom.', 32),('01c7653e-26ee-43b6-83cf-a869858ccc7d'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Which statement best explains why water has high surface tension?', 'Water molecules form hydrogen bonds with each other, creating cohesion at the surface', 'Cohesion via hydrogen bonding leads to a high surface tension at the air-water interface.', 33),('e41db307-4d49-4ba4-864f-3fca2794d90b'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'When water dissolves a cation such as Na+, which part of the water molecule orients toward the ion?', 'The oxygen atom (negative side) points toward the cation', 'Water is polar; the oxygen end (partial negative charge) faces the positively charged ion.', 34),('dd29916c-119c-4321-8919-1a131667838d'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'multiple_choice', 'Water has a high boiling point relative to many small molecules due to...', 'Hydrogen bonding between molecules (cohesion)', 'Hydrogen bonding between water molecules requires more energy to break, raising the boiling point.', 35),('5fbdcb88-a9d7-46af-8dcc-2abb0239d846'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'true_false', 'Water is essential for life because it acts only as a solvent and never participates in chemical reactions.', 'False', 'Water participates in hydrolysis and dehydration reactions, not just as a solvent.', 36),('0a8a4dcf-8dfe-41af-8acf-2e29c25ecdcf'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Explain two ways water''s polarity enables its role as a biological solvent.', 'Water''s polarity (partial negative on O and partial positive on H) allows it to dissolve ionic compounds by forming hydration shells around ions and to dissolve polar molecules by orienting itself to separate charges; it also enables water to participate in hydrolysis reactions.', 'Polarity enables solvent action and participation in biochemical reactions.', 37),('118b44a5-58dd-45fb-8672-be8f62bdff38'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'Describe how water molecules orient around a dissolved salt ion, naming which ends interact with cations vs anions.', 'Oxygen ends (with partial negative charge) face toward cations, while hydrogen ends face toward anions.', 'Hydration shells form with opposite ends of water oriented toward ions according to charge.', 38),('1e0f584a-8db7-45aa-8564-94dac0173911'::uuid, '4a739dbf-e683-4a84-8037-9393ee22638c'::uuid, 'fill_blank', 'If you have 5 water molecules, how many hydrogen atoms are present in total? Provide method and final unit.', '10 hydrogen atoms (5 molecules × 2 H per molecule)', 'Each H2O