) Carbon', FALSE, 3),('109c38f6-a2b7-4f2f-8f85-38b5e5d82d23'::uuid, '83b83c5a-eac4-40c4-89f2-88ba71e9ac03'::uuid, 'A) Cohesion', FALSE, 0),('5781fe87-01c1-4cc0-8263-2c3914f1f352'::uuid, '83b83c5a-eac4-40c4-89f2-88ba71e9ac03'::uuid, 'B) Adhesion', TRUE, 1),('1d3020cb-8c6b-4b5a-87af-c961e4e286a3'::uuid, '83b83c5a-eac4-40c4-89f2-88ba71e9ac03'::uuid, 'C) Osmosis', FALSE, 2),('02a2907e-ad08-46cd-8341-779f5f69a826'::uuid, '83b83c5a-eac4-40c4-89f2-88ba71e9ac03'::uuid, 'D) Diffusion', FALSE, 3),('7359e74a-3a03-4c25-813b-08b0d5d1d144'::uuid, '8a51adef-3932-422d-8eeb-1ca308ed5ae4'::uuid, 'A) Carbohydrates', FALSE, 0),('303d2135-7977-4214-85d0-0386bc212308'::uuid, '8a51adef-3932-422d-8eeb-1ca308ed5ae4'::uuid, 'B) Proteins', FALSE, 1),('238eae29-35f0-478b-8df4-be1240d31054'::uuid, '8a51adef-3932-422d-8eeb-1ca308ed5ae4'::uuid, 'C) Lipids', TRUE, 2),('367df4c9-9620-424a-8bed-fabb126063c8'::uuid, '8a51adef-3932-422d-8eeb-1ca308ed5ae4'::uuid, 'D) Nucleic acids', FALSE, 3),('3a1926c0-c61e-4ab2-8065-063aaac1cc65'::uuid, 'ddad3e00-24aa-4ad4-8fa8-7959c234e770'::uuid, 'True', TRUE, 0),('e09e906f-6be1-415c-8b65-4e842ce9773c'::uuid, 'ddad3e00-24aa-4ad4-8fa8-7959c234e770'::uuid, 'False', FALSE, 1),('88854e18-a7e2-4311-803e-f49b855bf036'::uuid, 'af065264-8b58-4823-8753-a9036bde89e0'::uuid, 'Water is a polar molecule that can dissolve many substances', TRUE, 0),('d3792029-ea7b-4e5d-8906-ddd1499a7a71'::uuid, 'af065264-8b58-4823-8753-a9036bde89e0'::uuid, 'Water is a non-polar solvent', FALSE, 1),('e55373ff-6f80-4a06-8e1a-3e6fb2899841'::uuid, 'af065264-8b58-4823-8753-a9036bde89e0'::uuid, 'Water has a low heat capacity', FALSE, 2),('0fcb91ae-96ac-4374-8fd5-31f349da87fd'::uuid, 'af065264-8b58-4823-8753-a9036bde89e0'::uuid, 'Water only exists as steam', FALSE, 3),('88d52716-154e-4c12-8a07-0fcc2c9b46d3'::uuid, '3e7ab41b-d164-441a-85e0-8e59e888e81a'::uuid, 'It participates in metabolic reactions and is essential for life', TRUE, 0),('a1938c3e-8ded-4a53-856b-9d79337639fd'::uuid, '3e7ab41b-d164-441a-8