0-c66e-4838-886d-11751e6f1baf'::uuid, 'D) It is recycled back to producers', FALSE, 3),('9d57e46f-27d2-498c-8e64-95360469f9ba'::uuid, 'ad48179c-a2ae-4002-8213-a5950078bc9f'::uuid, 'A) Energy is recycled within producers', FALSE, 0),('b0653cd9-3161-47d4-87bf-566617ad6e46'::uuid, 'ad48179c-a2ae-4002-8213-a5950078bc9f'::uuid, 'B) Energy is continually reused by decomposers', FALSE, 1),('6d78f7af-b8cc-408b-8fa1-35334862832e'::uuid, 'ad48179c-a2ae-4002-8213-a5950078bc9f'::uuid, 'C) Energy flows in one direction and is not recycled', TRUE, 2),('1153408d-616b-4628-8de1-5bb811e20175'::uuid, 'ad48179c-a2ae-4002-8213-a5950078bc9f'::uuid, 'D) Energy is created anew by sunlight', FALSE, 3),('ec9089f7-e7e0-4849-84f4-80bf28ed9a02'::uuid, 'bbe65e84-7749-4acc-88b7-75e0d4f4dc2d'::uuid, 'A) Water', FALSE, 0),('8cea4a4d-2e27-4eda-8b93-7d988cceec72'::uuid, 'bbe65e84-7749-4acc-88b7-75e0d4f4dc2d'::uuid, 'B) The Sun', TRUE, 1),('9ea840ff-816b-45ce-862f-b491d2c2bd7f'::uuid, 'bbe65e84-7749-4acc-88b7-75e0d4f4dc2d'::uuid, 'C) Soil nutrients', FALSE, 2),('4a653316-8e4c-458e-8831-43796808248f'::uuid, 'bbe65e84-7749-4acc-88b7-75e0d4f4dc2d'::uuid, 'D) Chemoautotrophic bacteria', FALSE, 3),('db1b017c-67d8-4839-82f8-1023e4ff78dc'::uuid, 'afdf4a50-3b07-4118-866c-9d6e66984ffb'::uuid, 'A decomposer', FALSE, 0),('a9204fb7-d8c8-4ffd-836d-6a50a71b3365'::uuid, 'afdf4a50-3b07-4118-866c-9d6e66984ffb'::uuid, 'A producer', TRUE, 1),('c4f3fee0-76f3-4fbb-806f-083b30206034'::uuid, 'afdf4a50-3b07-4118-866c-9d6e66984ffb'::uuid, 'A primary consumer', FALSE, 2),('d920da63-4e16-42cd-879f-b7bba7863191'::uuid, 'afdf4a50-3b07-4118-866c-9d6e66984ffb'::uuid, 'A secondary consumer', FALSE, 3),('14c90280-57a0-458d-882a-00752a03a3ff'::uuid, '5f01f07e-82ff-45fa-849f-93be03d09ab1'::uuid, 'Energy cycles within the same ecosystem.', FALSE, 0),('2e5327ee-b3f7-4104-8c7b-3730e9955a99'::uuid, '5f01f07e-82ff-45fa-849f-93be03d09ab1'::uuid, 'Energy flows in one direction from producers to higher trophic levels.', TRUE, 1),('de091b5f-84